/bin/bash -lc "cat > /tmp/build_lab_dns.py <<'PY'
from pathlib import Path
import re
root=Path('.')
zones=['.', 'com','net','edu','it','example.com','company.com','service.com','lab.net','tools.net','university.edu','campus.edu','unibo.it','comune.it','regione.it','shop.example.com','blog.example.com','dept.company.com','intranet.company.com','api.service.com','research.lab.net','ai.research.lab.net','data.research.lab.net','dev.lab.net','ci.tools.net','vpn.university.edu','courses.university.edu','portal.campus.edu','studenti.unibo.it','servizi.comune.it','dati.regione.it','org','io','gov','info','foundation.org','project.org','startup.io','platform.io','ministero.gov','news.info','archive.foundation.org','docs.project.org','api.startup.io','status.platform.io','open.ministero.gov','servizi.ministero.gov','local.news.info','media.news.info']
ips={i:re.search(r\"inet (10\\.\\d+\\.\\d+\\.\\d+)/24\",(root/f'pc{i}.startup').read_text()).group(1) for i in range(1,61)}
lookup={z:i for i,z in enumerate(zones,1)}
def ns(z): return 'ns.root.' if z=='.' else 'ns.'+z+'.'
def parent(z): return z.split('.',1)[1] if '.' in z else '.'
children={z:[] for z in zones}
for z in zones[1:]: children[parent(z)].append(z)
mail={'company.com','university.edu','dept.company.com','servizi.ministero.gov'}
for i,z in enumerate(zones,1):
 d=root/f'pc{i}'/'etc'/'bind'; d.mkdir(parents=True,exist_ok=True)
 fq='.' if z=='.' else z+'.'
 records=['"'$TTL 300'"',f'"'$ORIGIN {fq}'"',f'@ IN SOA {ns(z)} hostmaster.{\"root.\" if z==\".\" else z+\".\"} ( 2026110501 3600 600 604800 300 )',f'@ IN NS {ns(z)}',f'{ns(z)} IN A {ips[i]}']
 if z"'!='"'.': records.append(f'@ IN A {ips[i]}')
 if z in mail: records.extend([f'@ IN MX 10 mail.{z}.',f'mail.{z}. IN A {ips[i]}'])
 for c in children[z]: records.extend([f'{c}. IN NS {ns(c)}',f'{ns(c)} IN A {ips[lookup[c]]}'])
 (d/'db.zone').write_text('\\n'.join(records)+'\\n')
 (d/'named.conf').write_text(f'''options {{
    directory \"/var/cache/bind\";
    listen-on {{ any; }};
    listen-on-v6 {{ none; }};
    recursion no;
    allow-query {{ any; }};
    dnssec-validation no;
    pid-file \"/run/named-lab.pid\";
}};
zone \"{z}\" {{ type primary; file \"/etc/bind/db.zone\"; }};
''')
d=root/'pc50'/'etc'/'bind'; d.mkdir(parents=True,exist_ok=True)
(d/'root.hints').write_text(f'. 300 IN NS ns.root.\\nns.root. 300 IN A {ips[1]}\\n')
(d/'named.conf').write_text('''options {
    directory \"/var/cache/bind\";
    listen-on { any; };
    listen-on-v6 { none; };
    recursion yes;
    allow-query { any; };
    allow-recursion { 10.16.0.0/16; 127.0.0.1; };
    allow-query-cache { 10.16.0.0/16; 127.0.0.1; };
    dnssec-validation no;
    pid-file \"/run/named-lab.pid\";
};
zone \".\" { type hint; file \"/etc/bind/root.hints\"; };
''')
for i in range(1,61):
 p=root/f'pc{i}.startup'; s=p.read_text()
 s+='\\n# DNS lab configuration.\\nprintf \"nameserver '+ips[50]+'\\\\n\" > /etc/resolv.conf\\n'
 if i<=50: s+='mkdir -p /var/cache/bind /run\\nnamed -4 -c /etc/bind/named.conf\\n'
 p.write_text(s)
print('zones',len(zones),'delegations',sum(map(len,children.values())),'resolver',ips[50])
PY
python3 /tmp/build_lab_dns.py"

